class Solution { fun countPalindromes(s:String):Int{val mod=1_000_000_007L;val leftSingle=LongArray(10);val rightSingle=LongArray(10);val leftPair=Array(10){LongArray(10)};val rightPair=Array(10){LongArray(10)};for(character in s){val digit=character-'0';for(first in 0..9)rightPair[first][digit]+=rightSingle[first];rightSingle[digit]++};var answer=0L;for(character in s){val digit=character-'0';rightSingle[digit]--;for(second in 0..9)rightPair[digit][second]-=rightSingle[second];for(first in 0..9)for(second in 0..9)answer=(answer+leftPair[first][second]*rightPair[second][first])%mod;for(first in 0..9)leftPair[first][digit]+=leftSingle[first];leftSingle[digit]++};return answer.toInt()} }
